"use strict";exports.id=820,exports.ids=[820],exports.modules={6820:(a,b,c)=>{c.d(b,{Dn:()=>f,HQ:()=>e,ME:()=>d,dt:()=>g});let d={name:"Harkirat Singh",email:"hkkirat25@gmail.com",phone:"+91 88476 54698",location:"Patiala, India",linkedin:"https://www.linkedin.com/in/harkiratse/",github:"https://github.com/harkirat2023",resume:"/harkirat-singh-resume.pdf",availability:"Open to AI / full-stack roles \xb7 2027"},e=[{name:"Languages",items:["Java","Python","JavaScript","TypeScript","SQL"]},{name:"CS Fundamentals",items:["DSA","OOP","DBMS","Operating Systems","Computer Networks"]},{name:"Web & Realtime",items:["Next.js","FastAPI","REST design","JWT","WebSockets"]},{name:"Generative AI",items:["LangChain","Prompt Engineering","Vector DBs","RAG","Agent tool-calling"]},{name:"Data & Infra",items:["MySQL","PostgreSQL","MongoDB","Redis"]}],f=[{role:"AI Intern",org:"XTRAGRAD Technologies",date:"Aug 2026",summary:"Building exam-proctoring intelligence from webcam and audio streams.",bullets:["Tracked face, head pose, multiple people, and external devices with OpenCV, streamed through FastAPI.","Designed progressive warnings, risk scoring, violation timelines, and a live examiner view.","Automated post-session reports so reviewers can focus on high-risk sessions."],stack:["Python","OpenCV","FastAPI","MongoDB","JWT"]},{role:"Summer Project Intern",org:"Experiential Learning Centre, TIET",date:"Jun – Jul 2025",summary:"Explored passive, continuous authentication for mobile banking.",bullets:["Kept raw sensor signals on-device in a Split Federated Learning architecture.","Combined accelerometer, gyroscope, keystroke, and touch-heatmap signals into a behavioural profile."],stack:["Python","Split Federated Learning","Sensor Fusion"]},{role:"Joint Secretary",org:"IETE Students Forum, TIET",date:"May 2025 – May 2026",summary:"Ran a 27-person team across technical events for 450+ participants.",bullets:["Standardised budgets, timelines, and task allocation across concurrent projects.","Used engagement data to choose events to repeat; membership grew 40%."],stack:["Leadership","Operations"]}],g=[{slug:"symptomscope",index:"01",title:"SymptomScope AI",thesis:"A health triage workflow that pairs an explainable prediction with a grounded assistant.",role:"solo build",year:"Year not listed",stack:["Next.js","FastAPI","MongoDB","scikit-learn","LangChain","ChromaDB"],outcomes:[{value:"3-model",label:"ensemble"},{value:"~89%",label:"prediction accuracy"},{value:"12",label:"medical documents"}],problem:["A symptom score needs to show how it reached its recommendation. A conversational layer also needs a boundary between useful guidance and a case that should be escalated."],architecture:{layers:[{name:"Client",nodes:[{id:"ui",label:"Next.js",note:"Symptom flow, history, dashboard, and reports."}]},{name:"Service",nodes:[{id:"api",label:"FastAPI",note:"Coordinates prediction and assistant requests."},{id:"ensemble",label:"ML ensemble",note:"Combines three prediction models with SHAP explanations."},{id:"agent",label:"RAG assistant",note:"Retrieves from the medical document set through LangChain."}]},{name:"Data",nodes:[{id:"chroma",label:"ChromaDB",note:"Stores retrieved document vectors."},{id:"mongo",label:"MongoDB",note:"Stores authenticated user history."}]}]},decisions:[{decision:"Keep prediction and assistant as separate steps.",why:"The ensemble produces a score while retrieval provides grounded context.",tradeoff:"The user moves through a more explicit workflow instead of receiving one opaque answer."},{decision:"Expose SHAP explanations with the score.",why:"A prediction is more useful when its contributing signals can be inspected.",tradeoff:"The explanation adds detail to the result view."},{decision:"Retrieve from a bounded medical document set.",why:"The assistant needs a defined source for its responses.",tradeoff:"Coverage stays limited to the indexed documents."}],result:["Combines a three-model ensemble, SHAP explanations, and a RAG assistant over 12 medical documents.","Includes authentication, history, dashboards, and PDF/CSV reporting."],next:["Evaluate escalation thresholds with clinical review.","Expand the retrieval corpus only with traceable sources."],links:{live:"https://symptom-scope-ai.vercel.app",github:"https://github.com/harkirat2023/Symptom-Scope-AI"},glyph:"symptomscope"},{slug:"khata-box",index:"02",title:"KhataBox",thesis:"A retail platform that connects stock decisions, billing, and realtime updates.",role:"solo build",year:"Year not listed",stack:["Next.js","TypeScript","FastAPI","PostgreSQL","scikit-learn","Redis"],outcomes:[{value:"20+",label:"modules"},{value:"30+",label:"REST APIs"},{value:"Random Forest",label:"demand forecast"}],problem:["Retail workflows spread inventory, customer orders, and billing across disconnected tools. KhataBox brings those operations into one platform."],architecture:{layers:[{name:"Client",nodes:[{id:"next",label:"Next.js",note:"Retail dashboard and customer-facing workflows."}]},{name:"Service",nodes:[{id:"api",label:"FastAPI",note:"REST endpoints and role-aware workflows."},{id:"socket",label:"Socket.IO",note:"Pushes stock changes to connected clients."}]},{name:"Data",nodes:[{id:"db",label:"PostgreSQL",note:"Persists product and order records."},{id:"redis",label:"Redis",note:"Caches and distributes stock updates."}]}]},decisions:[{decision:"Separate REST operations from stock broadcasts.",why:"Most operations need a durable request/response path while stock changes need to reach open clients.",tradeoff:"Realtime clients must reconcile after reconnect."},{decision:"Use PostgreSQL for the retail records.",why:"Orders and inventory require durable relational data.",tradeoff:"Schema changes need deliberate migrations."},{decision:"Use a Random Forest for weekly demand forecasts.",why:"Sales history can inform restocking decisions.",tradeoff:"Forecasts support staff decisions rather than replace them."}],result:["Connected QR/barcode scanning, low-stock alerts, and PDF invoicing.","Added role-based JWT authentication, Redis caching, and responsive dashboards."],next:["Measure forecast quality against realised demand.","Add an explicit reconciliation view for reconnecting realtime clients."],links:{live:"https://khataboxapp.vercel.app",github:"https://github.com/harkirat2023/KhataBox--Inventory-B2C-Retail-Management-Platform"},glyph:"khatabox"},{slug:"intellimoney",index:"03",title:"IntelliMoney",thesis:"An expense platform that turns transaction patterns into a financial health score.",role:"solo build",year:"Year not listed",stack:["Python","React","FastAPI","MongoDB","scikit-learn","NLP"],outcomes:[{value:"TF-IDF",label:"text features"},{value:"Logistic Regression",label:"categoriser"},{value:"JWT",label:"authentication"}],problem:["Spending data is difficult to act on when categories and summaries require manual work. IntelliMoney automates categorisation and brings the results into a budgeting workflow."],architecture:{layers:[{name:"Input",nodes:[{id:"receipt",label:"Transactions",note:"Expense records enter the platform."}]},{name:"Service",nodes:[{id:"classify",label:"Categoriser",note:"TF-IDF and Logistic Regression assign categories."},{id:"api",label:"FastAPI",note:"Serves authenticated financial workflows."}]},{name:"Data",nodes:[{id:"mongo",label:"MongoDB",note:"Stores user financial data."},{id:"ui",label:"Dashboard",note:"Displays budgets and financial health."}]}]},decisions:[{decision:"Automate categorisation with TF-IDF and Logistic Regression.",why:"Text features provide a practical way to map expense descriptions to categories.",tradeoff:"Ambiguous descriptions still need user correction."},{decision:"Keep financial services behind authenticated APIs.",why:"Budget records are user-specific data.",tradeoff:"The frontend depends on token lifecycle handling."},{decision:"Present scores through interactive dashboards.",why:"Users need to inspect patterns rather than receive a single static score.",tradeoff:"The score remains a summary of the underlying transactions."}],result:["Built expense categorisation, budgeting, and personalised financial health scoring.","Added dashboards and secure FastAPI/MongoDB services."],next:["Add a correction loop to improve category quality.","Explain score movement alongside individual budget changes."],links:{live:"https://intellimoney.vercel.app",github:"https://github.com/harkirat2023/IntelliMoney-AI-Powered-Financial-Health-Scoring-Platform"},glyph:"intellimoney"},{slug:"supply-chain-otif",index:"04",title:"Supply Chain Control Tower",thesis:"An analytics project that turns operational data into an OTIF view for decisions.",role:"analysis project",year:"Year not listed",stack:["Excel","SQL","Power BI","Analytics"],outcomes:[{value:"OTIF",label:"delivery KPI"},{value:"SQL",label:"data analysis"},{value:"Power BI",label:"visualisation"}],problem:["Supply-chain performance is hard to inspect when source data and delivery measures are disconnected. The control tower frames the data around operational KPIs."],architecture:{layers:[{name:"Input",nodes:[{id:"source",label:"Excel / SQL",note:"Operational data is prepared and queried."}]},{name:"Model",nodes:[{id:"model",label:"KPI layer",note:"Structures on-time-in-full measures."}]},{name:"Output",nodes:[{id:"bi",label:"Power BI",note:"Presents the KPI view for analysis."}]}]},decisions:[{decision:"Center the analysis on OTIF.",why:"The measure combines on-time and in-full delivery performance.",tradeoff:"A single KPI needs supporting breakdowns to explain misses."},{decision:"Use SQL to structure the analysis.",why:"Queryable transformations make the source logic inspectable.",tradeoff:"Data quality issues remain visible and need handling."},{decision:"Present the output in Power BI.",why:"A visual KPI layer helps compare operational patterns.",tradeoff:"The dashboard is only as reliable as its source data."}],result:["Structured a supply-chain KPI analysis around OTIF.","Built a Power BI view from Excel and SQL data."],next:["Add clear data-quality checks to the ingestion path.","Separate late and incomplete delivery drivers in the KPI breakdown."],glyph:"supplychain"},{slug:"churnsight",index:"05",title:"ChurnSight",thesis:"An in-progress churn analysis project pairing a model with feature explanations.",role:"analysis project",year:"Building",stack:["Python","XGBoost","SHAP","Streamlit"],outcomes:[{value:"XGBoost",label:"model"},{value:"SHAP",label:"explanations"},{value:"Streamlit",label:"interface"}],problem:["A churn score alone does not explain which subscriber signals deserve attention. ChurnSight is being built to pair classification with interpretable feature contributions."],architecture:{layers:[{name:"Input",nodes:[{id:"data",label:"Subscribers",note:"Subscriber records provide model features."}]},{name:"Model",nodes:[{id:"xgb",label:"XGBoost",note:"Estimates churn risk from the prepared features."},{id:"shap",label:"SHAP",note:"Explains feature contributions to predictions."}]},{name:"Output",nodes:[{id:"streamlit",label:"Streamlit",note:"Presents model outputs for inspection."}]}]},decisions:[{decision:"Pair XGBoost with SHAP.",why:"The model score needs feature-level context for review.",tradeoff:"Explanations describe model behaviour, not causal drivers."},{decision:"Use Streamlit for the analysis interface.",why:"It provides a direct way to inspect model outputs during development.",tradeoff:"The project remains an analysis tool rather than a production system."},{decision:"Keep the project marked as in progress.",why:"The source r\xe9sum\xe9 says it is being built.",tradeoff:"No shipped-product claim is made."}],result:["Building an explainable churn analysis workflow.","Uses XGBoost, SHAP, and Streamlit."],next:["Validate the model against a held-out dataset.","Inspect explanation stability across subscriber segments."],glyph:"churnsight"}]}};